import {escapeHTML as e} from './store.js';
export function initAppearance(state,{save,modal,field,onProfile}){
 const apply=()=>{document.body.dataset.palette=['sapphire','pond','aurora'].includes(state.palette)?state.palette:'sapphire';document.body.classList.toggle('dark',state.theme==='dark');document.querySelector('#profileButton').textContent=(state.profileName||'Ana').trim().slice(0,1).toUpperCase();};
 const trigger=document.querySelector('#themeButton');trigger.title='Personalizar tema';trigger.setAttribute('aria-label','Personalizar tema');const menu=document.createElement('div');menu.className='appearance-popover';menu.hidden=true;menu.innerHTML=`<span class="eyebrow">APARÊNCIA DO ATELIÊ</span><h2>Escolha sua atmosfera</h2><div class="theme-choices">${[['sapphire','Safira','Azul profundo e dourado',['#112250','#3C507D','#E0C58F','#F5F0E9']],['pond','Lago','Verdes, musgo e bege',['#0A3323','#839958','#F7F4D5','#D3968C']],['aurora','Aurora','Lilás, azul e tons suaves',['#B8D8E6','#CBB7E6','#F4A7C4','#F6F2E8']]].map(([id,name,desc,colors])=>`<button data-palette-choice="${id}" aria-pressed="false"><span class="theme-swatches">${colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span><span><strong>${name}</strong><small>${desc}</small></span><span class="theme-check">✓</span></button>`).join('')}</div><div class="appearance-modes"><button data-mode-choice="light">☼ Claro</button><button data-mode-choice="dark">☾ Escuro</button></div>`;document.querySelector('.top-actions').append(menu);
 function sync(){menu.querySelectorAll('[data-palette-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.paletteChoice===(state.palette||'sapphire'))));menu.querySelectorAll('[data-mode-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.modeChoice===(state.theme||'light'))));}trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));sync();};menu.querySelectorAll('[data-palette-choice]').forEach(b=>b.onclick=()=>{state.palette=b.dataset.paletteChoice;apply();sync();save();});menu.querySelectorAll('[data-mode-choice]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.modeChoice;apply();sync();save();});document.addEventListener('click',ev=>{if(!menu.contains(ev.target)&&!trigger.contains(ev.target)){menu.hidden=true;trigger.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!menu.hidden){menu.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.focus();}});
 document.querySelector('#profileButton').onclick=()=>modal('Seu espaço criativo',field('Como podemos chamar você?','name',state.profileName||'Ana','text',true)+'<p class="help">Este perfil é salvo apenas neste navegador.</p>',fd=>{state.profileName=String(fd.get('name')).trim().slice(0,60)||'Ana';apply();save();onProfile();});document.querySelector('#helpButton').onclick=()=>modal('Seu ateliê, sempre por perto','<div class="atelier-help"><p><strong>Meu universo</strong> reúne suas ferramentas de escrita e criação.</p><p><strong>Ctrl + K</strong> encontra documentos, personagens e lugares.</p><p>Em <strong>Cenas</strong>, escreva com suas referências ao lado. Expanda o editor para se concentrar.</p><p>Em <strong>Conexões</strong>, arraste o ponto de um cartão até outro para conectá-los.</p><p>Em <strong>Configurações</strong>, escolha as abas do ambiente e exporte um backup.</p></div>',()=>{},{noActions:true});apply();
}
